-- Create date: 20/03/2021
-- Description:	Se optimiza la consulta para la pantalla detalle_pedido del issue 984
-- =============================================CREATE PROCEDURE SP_ObtenerNumPedidoConsecutivoxOperacion --6812, 0	@IdOperacion INT, 	@IdSubContratista INTAS	BEGIN		SELECT pedido.IdPedido, 				pedido.IdSubcontratista		FROM dbo.TA_Operacion TAO		INNER JOIN	dbo.MM_SolicitudPedido solPed			ON TAO.IdDocumento = solPed.IdSolicitudPedido		INNER JOIN	dbo.MM_Pedido pedido			ON 			solPed.IdSolicitudPedido = pedido.IdSolicitudPedido 			AND TAO.NoVersion = pedido.Version		WHERE TAO.IdOperacion = @IdOperacion			--AND pedido.IdSubcontratista = @IdSubContratista	END